package offline;
import java.util.ArrayList;
final class Journal {
    private final ArrayList<Runnable> undo = new ArrayList<>();
    void add(Runnable r) { undo.add(r); }
    void commit() { undo.clear(); }
    void rollback() { for (int i = undo.size() - 1; i >= 0; i--) undo.get(i).run(); undo.clear(); }
}
```

