private static long reconstruct(long raw, int width, long expected) {
    long m = 1L << (8 * width);   // width ≤ 4 → m ≤ 2^32, fine
    long delta = expected - raw;  // could be negative
    long k = Math.floorDiv(delta, m);  // floor division → could be negative
    if (k < 0) k = 0;
    long c0 = raw + k * m;      // ≤ expected (if k>0) or raw
    long c1 = c0 + m;
    // choose closer; tie → larger
    long d0 = Math.abs(expected - c0), d1 = c1 - expected;
    return (d1 <= d0) ? c1 : c0;
}
