package offline;

import java.util.ArrayList;

/** Reversible transaction log: every mutation registers its own undo action. */
final class Journal {
    private final ArrayList<Runnable> undo = new ArrayList<>();

    void add(Runnable action) {
        undo.add(action);
    }

    void commit() {
        undo.clear();
    }

    void rollback() {
        for (int i = undo.size() - 1; i >= 0; i--) {
            undo.get(i).run();
        }
        undo.clear();
    }
}
