package offline;

/** Introsort over two parallel long arrays (primary key first). */
final class ParallelSort {
    private static final int INSERTION = 24;

    private ParallelSort() {}

    static void sort(long[] key, long[] val, int n) {
        if (n < 2) {
            return;
        }
        quick(key, val, 0, n - 1, 2 * (31 - Integer.numberOfLeadingZeros(n)));
    }

    private static void quick(long[] a, long[] b, int lo, int hi, int depth) {
        while (hi - lo > INSERTION) {
            if (depth <= 0) {
                heap(a, b, lo, hi);
                return;
            }
            depth--;
            int mid = partition(a, b, lo, hi);
            if (mid - lo < hi - mid) {
                quick(a, b, lo, mid, depth);
                lo = mid + 1;
            } else {
                quick(a, b, mid + 1, hi, depth);
                hi = mid;
            }
        }
        insertion(a, b, lo, hi);
    }

    private static int partition(long[] a, long[] b, int lo, int hi) {
        int mid = (lo + hi) >>> 1;
        if (a[mid] < a[lo]) {
            swap(a, b, lo, mid);
        }
        if (a[hi] < a[lo]) {
            swap(a, b, lo, hi);
        }
        if (a[hi] < a[mid]) {
            swap(a, b, mid, hi);
        }
        long pivot = a[mid];
        int i = lo - 1;
        int j = hi + 1;
        while (true) {
            do {
                i++;
            } while (a[i] < pivot);
            do {
                j--;
            } while (a[j] > pivot);
            if (i >= j) {
                return j;
            }
            swap(a, b, i, j);
        }
    }

    private static void insertion(long[] a, long[] b, int lo, int hi) {
        for (int i = lo + 1; i <= hi; i++) {
            long ka = a[i];
            long kb = b[i];
            int j = i - 1;
            while (j >= lo && a[j] > ka) {
                a[j + 1] = a[j];
                b[j + 1] = b[j];
                j--;
            }
            a[j + 1] = ka;
            b[j + 1] = kb;
        }
    }

    private static void heap(long[] a, long[] b, int lo, int hi) {
        int n = hi - lo + 1;
        for (int i = n / 2 - 1; i >= 0; i--) {
            sift(a, b, lo, n, i);
        }
        for (int i = n - 1; i > 0; i--) {
            swap(a, b, lo, lo + i);
            sift(a, b, lo, i, 0);
        }
    }

    private static void sift(long[] a, long[] b, int lo, int n, int i) {
        long ka = a[lo + i];
        long kb = b[lo + i];
        while (true) {
            int child = 2 * i + 1;
            if (child >= n) {
                break;
            }
            int right = child + 1;
            if (right < n && a[lo + right] > a[lo + child]) {
                child = right;
            }
            if (a[lo + child] <= ka) {
                break;
            }
            a[lo + i] = a[lo + child];
            b[lo + i] = b[lo + child];
            i = child;
        }
        a[lo + i] = ka;
        b[lo + i] = kb;
    }

    private static void swap(long[] a, long[] b, int i, int j) {
        if (i == j) {
            return;
        }
        long t = a[i];
        a[i] = a[j];
        a[j] = t;
        t = b[i];
        b[i] = b[j];
        b[j] = t;
    }
}
